var pages = [].concat($('personality p1').all(), $('personality p2').all());
var users = {}; var tickets = []; var errors = [];
pages.forEach(function (it) { var b = it.json || {}; if (b.error) errors.push(String(JSON.stringify(b.error)).slice(0, 160)); (b.users || []).forEach(function (u) { users[u.id] = u; }); (b.tickets || []).forEach(function (t) { tickets.push(t); }); });
var seen = {}; var out = [];
tickets.forEach(function (t) {
  if (!t || !t.id || seen[t.id]) return; seen[t.id] = true;
  var u = users[t.requester_id] || {}; var uf = u.user_fields || {};
  var ufKeys = Object.keys(uf).filter(function (k) { return uf[k] !== null && uf[k] !== '' && uf[k] !== false; });
  out.push({ json: { id: t.id, channel: (t.via && t.via.channel) || 'unknown', tz: u.time_zone || null, locale: u.locale || null, user_field_keys: ufKeys, fetch_errors: errors } });
});
if (!out.length) out.push({ json: { id: 0, empty: true, fetch_errors: errors } });
