function cls(ua) { ua = String(ua || ''); if (!ua) return 'none'; if (/Mozilla\/|AppleWebKit|Chrome\/|Safari\/|Firefox\/|Edg\//.test(ua)) return 'browser'; return 'server:' + ua.split(/[\s(;]/)[0].slice(0, 40); }
function country(loc) { if (!loc) return null; var p = String(loc).split(','); return p[p.length - 1].trim() || null; }
function mask(ip) { if (!ip) return null; var p = String(ip).split('.'); return p.length === 4 ? p[0] + '.' + p[1] + '.x.x' : String(ip).slice(0, 8) + '...'; }
function top(map, n) { return Object.keys(map).map(function (k) { return [k, map[k]]; }).sort(function (a, b) { return b[1] - a[1]; }).slice(0, n); }
function analyse(brand, splitName, auditsName, fieldsName) {
  var tickets = $(splitName).all().map(function (i) { return i.json; }).filter(function (t) { return t.id; });
  var meta = {}; var auditErrors = 0;
  $(auditsName).all().forEach(function (it) {
    var b = it.json || {}; if (b.error) { auditErrors++; return; }
    var aud = b.audits || []; if (!aud.length) return;
    var created = null;
    for (var i = 0; i < aud.length; i++) { var ev = aud[i].events || []; if (ev.some(function (e) { return e.type === 'Create'; })) { created = aud[i]; break; } }
    if (!created) created = aud[0];
    var sys = (created.metadata && created.metadata.system) || {};
    meta[created.ticket_id] = { ip: sys.ip_address || null, location: sys.location || null, client: sys.client || null };
  });
  var channels = {}, byCh = {}, tz = {}, loc = {}, samples = [];
  tickets.forEach(function (t) {
    channels[t.channel] = (channels[t.channel] || 0) + 1;
    var m = meta[t.id] || {};
    var c = byCh[t.channel] = byCh[t.channel] || { n: 0, with_location: 0, ips: {}, clients: {}, countries: {} };
    c.n++; if (m.location) c.with_location++;
    if (m.ip) c.ips[m.ip] = (c.ips[m.ip] || 0) + 1;
    var k = cls(m.client); c.clients[k] = (c.clients[k] || 0) + 1;
    var co = country(m.location); if (co) c.countries[co] = (c.countries[co] || 0) + 1;
    if (t.tz) tz[t.tz] = (tz[t.tz] || 0) + 1;
    if (t.locale) loc[t.locale] = (loc[t.locale] || 0) + 1;
    if (samples.length < 12) samples.push({ id: t.id, channel: t.channel, client: k, ip: mask(m.ip), country: co, tz: t.tz });
  });
  var chOut = {};
  Object.keys(byCh).forEach(function (ch) {
    var c = byCh[ch]; var ipTop = top(c.ips, 3);
    var ipTotal = Object.keys(c.ips).reduce(function (s, k) { return s + c.ips[k]; }, 0);
    chOut[ch] = { n: c.n, location_rate: c.n ? Math.round(c.with_location / c.n * 100) + '%' : '-', distinct_ips: Object.keys(c.ips).length, top_ip_share: ipTotal ? Math.round(ipTop[0][1] / ipTotal * 100) + '%' : '-', top_ips_masked: ipTop.map(function (x) { return mask(x[0]) + ' x' + x[1]; }), clients: top(c.clients, 5), top_countries: top(c.countries, 8) };
  });
  var fieldTitles = [];
  try { var fj = $(fieldsName).first().json || {}; fieldTitles = (fj.ticket_fields || []).filter(function (f) { return /countr|locat|region|state|geo|nation/i.test(String(f.title || '')); }).map(function (f) { return f.id + ': ' + f.title + ' (' + f.type + (f.active ? '' : ', inactive') + ')'; }); } catch (e) {}
  var ufKeys = {}; tickets.forEach(function (t) { (t.user_field_keys || []).forEach(function (k) { ufKeys[k] = (ufKeys[k] || 0) + 1; }); });
  var tzTop = top(tz, 6); var tzTotal = Object.keys(tz).reduce(function (s, k) { return s + tz[k]; }, 0);
  var firstErr = $(splitName).all().map(function (i) { return i.json.fetch_errors || []; })[0] || [];
  return { brand: brand, sampled: tickets.length, fetch_errors: firstErr, audit_errors: auditErrors, audits_matched: Object.keys(meta).length, channels: channels, by_channel: chOut, tz_top: tzTop, tz_top_share: tzTotal ? Math.round(tzTop[0][1] / tzTotal * 100) + '%' : '-', locale_top: top(loc, 6), country_like_ticket_fields: fieldTitles, user_fields_populated: top(ufKeys, 10), samples: samples };
}
return [ { json: analyse('personality', 'personality split', 'personality audits', 'personality fields') }, { json: analyse('myqrcode', 'myqrcode split', 'myqrcode audits', 'myqrcode fields') } ];
